 "A Dutch painter who reduced art to black lines and blocks of primary colour.": {
  "es": "Un pintor neerlandés que redujo el arte a líneas negras y bloques de colores primarios.",
  "ar": "رسام هولندي اختزل الفن في خطوط سوداء وكتل من الألوان الأساسية.",
  "zh": "一位荷兰画家，把艺术简化为黑色线条和原色色块。",
  "sw": "Mchoraji wa Kiholanzi aliyepunguza sanaa kuwa mistari myeusi na vitalu vya rangi za msingi.",
  "sv": "En nederländsk målare som reducerade konsten till svarta linjer och block i primärfärger.",
  "de": "Ein niederländischer Maler, der Kunst auf schwarze Linien und Flächen in Grundfarben reduzierte.",
  "pt": "Um pintor holandês que reduziu a arte a linhas pretas e blocos de cores primárias.",
  "fr": "Un peintre néerlandais qui a réduit l'art à des lignes noires et des blocs de couleurs primaires."
 },
 "How this picture links to it": {
  "es": "Cómo se relaciona esta imagen",
  "ar": "كيف ترتبط هذه الصورة بالأداة",
  "zh": "这幅画与本工具的关系",
  "sw": "Jinsi picha hii inavyohusiana",
  "sv": "Hur bilden hänger ihop med verktyget",
  "de": "Wie dieses Bild mit dem Werkzeug zusammenhängt",
  "pt": "Como esta imagem se relaciona com a ferramenta",
  "fr": "Le lien entre cette image et l'outil"
 },
 "Thick black lines dividing white, red, blue and yellow rectangles are his Compositions. In front stands an original robot drawn in the same colours, holding a star that fits this tool.": {
  "es": "Gruesas líneas negras que dividen rectángulos blancos, rojos, azules y amarillos son sus Composiciones. Delante hay un robot original dibujado con los mismos colores, que sostiene una estrella acorde con esta herramienta.",
  "ar": "خطوط سوداء سميكة تقسم مستطيلات بيضاء وحمراء وزرقاء وصفراء هي \"تكويناته\". وفي المقدمة يقف روبوت أصلي مرسوم بالألوان نفسها، يحمل نجمة تناسب هذه الأداة.",
  "zh": "粗黑线条分隔出白、红、蓝、黄色矩形，这就是他的《构图》系列。前方站着一个用同样颜色画成的原创机器人，手里拿着一颗与本工具相配的星星。",
  "sw": "Mistari minene myeusi inayogawa mistatili myeupe, myekundu, ya bluu na ya njano ndiyo Compositions zake. Mbele amesimama roboti halisi aliyechorwa kwa rangi zilezile, akishika nyota inayolingana na zana hii.",
  "sv": "Tjocka svarta linjer som delar upp vita, röda, blå och gula rektanglar är hans Kompositioner. Framför står en egen robot tecknad i samma färger, med en stjärna som passar det här verktyget.",
  "de": "Dicke schwarze Linien, die weiße, rote, blaue und gelbe Rechtecke teilen, sind seine Kompositionen. Davor steht ein eigener Roboter in denselben Farben, der einen Stern hält, der zu diesem Werkzeug passt.",
  "pt": "Linhas pretas grossas dividindo retângulos brancos, vermelhos, azuis e amarelos são suas Composições. Na frente está um robô original desenhado nas mesmas cores, segurando uma estrela que combina com esta ferramenta.",
  "fr": "D'épaisses lignes noires séparant des rectangles blancs, rouges, bleus et jaunes sont ses Compositions. Devant se tient un robot original dessiné dans les mêmes couleurs, tenant une étoile qui convient à cet outil."
 },
 "Made by Claude, an AI by Anthropic: an original homage drawn in code. Nothing is copied from real paintings.": {
  "es": "Hecha por Claude, una IA de Anthropic: un homenaje original dibujado con código. No se copia nada de pinturas reales.",
  "ar": "من صنع Claude، ذكاء اصطناعي من Anthropic: تكريم أصلي مرسوم بالكود. لا شيء منسوخ من لوحات حقيقية.",
  "zh": "由 Anthropic 的 AI Claude 制作：一幅用代码绘制的原创致敬作品，没有复制任何真实画作。",
  "sw": "Imetengenezwa na Claude, AI ya Anthropic: heshima asilia iliyochorwa kwa msimbo. Hakuna kilichonakiliwa kutoka kwa michoro halisi.",
  "sv": "Gjord av Claude, en AI från Anthropic: en egen hyllning ritad med kod. Ingenting är kopierat från riktiga målningar.",
  "de": "Gemacht von Claude, einer KI von Anthropic: eine originelle Hommage, in Code gezeichnet. Nichts ist von echten Gemälden kopiert.",
  "pt": "Feito pelo Claude, uma IA da Anthropic: uma homenagem original desenhada em código. Nada é copiado de pinturas reais.",
  "fr": "Réalisé par Claude, une IA d'Anthropic : un hommage original dessiné en code. Rien n'est copié de vrais tableaux."
 },
