 "Cube Forge": {
  "es": "Cube Forge",
  "ar": "Cube Forge",
  "zh": "Cube Forge",
  "sw": "Cube Forge",
  "sv": "Cube Forge",
  "de": "Cube Forge",
  "pt": "Cube Forge",
  "fr": "Cube Forge"
 },
 "Learn to solve a twisty cube in 3D. Choose how many layers it has — from a 2×2 to a 10×10, or a cuboid like the 3×3×2 — turn it by dragging or with the move buttons, learn the beginner method one step at a time, and let it solve your own cube with you.": {
  "es": "Aprende a resolver un cubo de rompecabezas en 3D. Elige cuántas capas tiene, de un 2×2 a un 10×10, o un cuboide como el 3×3×2; gíralo arrastrando o con los botones de movimiento, aprende el método para principiantes paso a paso y deja que resuelva tu propio cubo contigo.",
  "ar": "تعلّم حلّ مكعب الألغاز ثلاثي الأبعاد. اختر عدد طبقاته — من 2×2 إلى 10×10، أو متوازي مستطيلات مثل 3×3×2 — وأدِره بالسحب أو بأزرار الحركة، وتعلّم طريقة المبتدئين خطوة بخطوة، ودعه يحلّ مكعبك معك.",
  "zh": "学习在 3D 中还原魔方。选择层数——从 2×2 到 10×10，或 3×3×2 这样的长方体魔方——拖动或用转动按钮来转，一步步学习入门解法，并让它陪你还原你自己的魔方。",
  "sw": "Jifunze kutatua mchemraba unaozunguka kwa 3D. Chagua una tabaka ngapi — kuanzia 2×2 hadi 10×10, au mstatili kama 3×3×2 — uzungushe kwa kuburuta au kwa vitufe vya mizunguko, jifunze mbinu ya mwanzo hatua kwa hatua, na uache ikusaidie kutatua mchemraba wako mwenyewe.",
  "sv": "Lär dig lösa en vridkub i 3D. Välj hur många lager den har — från 2×2 till 10×10, eller en kuboid som 3×3×2 — vrid den genom att dra eller med knapparna, lär dig nybörjarmetoden ett steg i taget och låt den lösa din egen kub tillsammans med dig.",
  "de": "Lerne, einen Zauberwürfel in 3D zu lösen. Wähle, wie viele Ebenen er hat – vom 2×2 bis zum 10×10 oder ein Quader wie der 3×3×2 –, dreh ihn durch Ziehen oder mit den Zugtasten, lerne die Anfängermethode Schritt für Schritt und lass dir beim Lösen deines eigenen Würfels helfen.",
  "pt": "Aprenda a resolver um cubo mágico em 3D. Escolha quantas camadas ele tem — de 2×2 a 10×10, ou um cuboide como o 3×3×2 —, gire arrastando ou com os botões de movimento, aprenda o método para iniciantes passo a passo e deixe que ele resolva o seu próprio cubo com você.",
  "fr": "Apprenez à résoudre un casse-tête cubique en 3D. Choisissez son nombre de couches — du 2×2 au 10×10, ou un pavé comme le 3×3×2 —, tournez-le en glissant ou avec les boutons de mouvement, apprenez la méthode débutant étape par étape et laissez-le résoudre votre propre cube avec vous."
 },
