 "A side that is not square (for example 3 × 2) can only turn halfway, like on a real cuboid.": {
  "es": "Un lado que no es cuadrado (por ejemplo 3 × 2) solo puede girar media vuelta, como en un cuboide real.",
  "ar": "الوجه غير المربع (مثل 3 × 2) لا يدور إلا نصف دورة، كما في متوازي مستطيلات حقيقي.",
  "zh": "不是正方形的面（例如 3 × 2）只能转半圈，就像真实的长方体魔方。",
  "sw": "Upande usio mraba (kwa mfano 3 × 2) unaweza kuzunguka nusu tu, kama kwenye mstatili halisi.",
  "sv": "En sida som inte är kvadratisk (till exempel 3 × 2) kan bara vridas ett halvt varv, som på en riktig kuboid.",
  "de": "Eine nicht quadratische Seite (zum Beispiel 3 × 2) lässt sich nur halb drehen, wie bei einem echten Quader.",
  "pt": "Um lado que não é quadrado (por exemplo 3 × 2) só gira meia volta, como num cuboide real.",
  "fr": "Un côté non carré (par exemple 3 × 2) ne peut faire qu’un demi-tour, comme sur un vrai pavé."
 },
