 "Drag a sticker on the 3D cube to turn its layer, drag the background to look around. Keys: U D L R F B (Shift for ′), M E S, X Y Z, Ctrl+Z to undo.": {
  "es": "Arrastra una pegatina del cubo 3D para girar su capa; arrastra el fondo para mirar alrededor. Teclas: U D L R F B (Mayús para ′), M E S, X Y Z, Ctrl+Z para deshacer.",
  "ar": "اسحب ملصقًا على المكعب ثلاثي الأبعاد لتدوير طبقته، واسحب الخلفية للنظر حوله. المفاتيح: U D L R F B (Shift لـ ′)، M E S، X Y Z، Ctrl+Z للتراجع.",
  "zh": "拖动 3D 魔方上的色块可转动该层，拖动背景可环视。按键：U D L R F B（Shift 为 ′）、M E S、X Y Z，Ctrl+Z 撤销。",
  "sw": "Buruta kibandiko kwenye mchemraba wa 3D kuzungusha tabaka lake, buruta mandharinyuma kutazama pande zote. Vitufe: U D L R F B (Shift kwa ′), M E S, X Y Z, Ctrl+Z kutendua.",
  "sv": "Dra i en klisterlapp på 3D-kuben för att vrida dess lager, dra i bakgrunden för att se dig omkring. Tangenter: U D L R F B (Skift för ′), M E S, X Y Z, Ctrl+Z för att ångra.",
  "de": "Zieh an einem Aufkleber des 3D-Würfels, um seine Ebene zu drehen, zieh am Hintergrund, um dich umzusehen. Tasten: U D L R F B (Umschalt für ′), M E S, X Y Z, Strg+Z zum Rückgängigmachen.",
  "pt": "Arraste um adesivo do cubo 3D para girar a camada, arraste o fundo para olhar em volta. Teclas: U D L R F B (Shift para ′), M E S, X Y Z, Ctrl+Z para desfazer.",
  "fr": "Faites glisser un autocollant du cube 3D pour tourner sa couche, faites glisser le fond pour regarder autour. Touches : U D L R F B (Maj pour ′), M E S, X Y Z, Ctrl+Z pour annuler."
 },
