  "ar": "🔒 كل شيء يعمل في متصفحك. يُحفظ مكعبك وأوقاتك على هذا الجهاز.",
  "zh": "🔒 一切都在你的浏览器中运行。你的魔方和成绩保存在本设备上。",
  "sw": "🔒 Kila kitu kinafanya kazi kwenye kivinjari chako. Mchemraba wako na nyakati zako zinahifadhiwa kwenye kifaa hiki.",
  "sv": "🔒 Allt körs i webbläsaren. Din kub och dina tider sparas på enheten.",
  "de": "🔒 Alles läuft in deinem Browser. Würfel und Zeiten werden auf diesem Gerät gespeichert.",
  "pt": "🔒 Tudo roda no seu navegador. Seu cubo e seus tempos ficam salvos neste aparelho.",
