 "Solve my cube": {
  "es": "Resolver mi cubo",
  "ar": "حلّ مكعبي",
  "zh": "还原我的魔方",
  "sw": "Tatua mchemraba wangu",
  "sv": "Lös min kub",
  "de": "Meinen Würfel lösen",
  "pt": "Resolver meu cubo",
  "fr": "Résoudre mon cube"
 },
 ". You get the beginner method step by step: every move is explained and highlighted on the cube, so you can follow along with a real cube in your hands.": {
  "es": ". Obtienes el método para principiantes paso a paso: cada movimiento se explica y se resalta en el cubo, para que puedas seguirlo con un cubo real en las manos.",
  "ar": "‏. تحصل على طريقة المبتدئين خطوة بخطوة: كل حركة مشروحة ومميّزة على المكعب، لتتابع بمكعب حقيقي في يديك.",
  "zh": "。你会一步步得到入门解法：每一步都会解释并在魔方上高亮，方便你拿着真魔方跟着做。",
  "sw": ". Unapata mbinu ya mwanzo hatua kwa hatua: kila mzunguko unaelezwa na kuangaziwa kwenye mchemraba, ili ufuatilie ukiwa na mchemraba halisi mikononi.",
  "sv": ". Du får nybörjarmetoden steg för steg: varje drag förklaras och markeras på kuben, så att du kan följa med på en riktig kub i händerna.",
  "de": ". Du bekommst die Anfängermethode Schritt für Schritt: Jeder Zug wird erklärt und auf dem Würfel hervorgehoben, sodass du mit einem echten Würfel in der Hand mitmachen kannst.",
  "pt": ". Você recebe o método para iniciantes passo a passo: cada movimento é explicado e destacado no cubo, para acompanhar com um cubo real nas mãos.",
  "fr": ". Vous obtenez la méthode débutant pas à pas : chaque mouvement est expliqué et mis en évidence sur le cube, pour suivre avec un vrai cube en main."
 },
