  "sv": "Två bitar har bytt plats, så de gula kanterna kan inte riktas upp. Kontrollera färgerna du angav, eller ta ut två kanter och byt plats på dem.",
  "de": "Zwei Steine sind vertauscht, daher lassen sich die gelben Kanten nicht ausrichten. Prüf die eingegebenen Farben oder nimm zwei Kanten heraus und tausche sie.",
